using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 [InitializeOnLoad] public static class LocalTacticalVerification {
  static double start;static int phase;static readonly List<string> results=new List<string>();
  static LocalTacticalVerification(){if(SessionState.GetBool("LocalVerify",false)){start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;Application.logMessageReceived+=Log;}}
  public static void Run(){File.WriteAllText("local-runtime-errors.txt","");LocalTacticalInstaller.Build();SessionState.SetBool("LocalVerify",true);start=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;Application.logMessageReceived+=Log;EditorApplication.EnterPlaymode();}
  static void Check(bool value,string label){if(!value)throw new Exception(label);results.Add("PASS "+label);}
  static void Log(string text,string stack,LogType type){if(type==LogType.Exception||type==LogType.Error){File.AppendAllText("local-runtime-errors.txt",text+"\n"+stack+"\n");}}
  static void Poll(){try{
   if(EditorApplication.timeSinceStartup-start>150)throw new Exception("Runtime timeout");if(!EditorApplication.isPlaying||Time.time<1.5f)return;var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(w==null||!w.Initialized)return;
   if(phase==0){
    foreach(var behaviour in w.GetComponents<MonoBehaviour>())if(behaviour.GetType().Name.StartsWith("AI"))behaviour.enabled=false;
    var local=w.GetComponent<LocalTacticalBattle>();var selection=w.GetComponent<ArmySelection>();var hud=UnityEngine.Object.FindObjectOfType<CampaignHUD>();
    Check(LocalTacticalBattle.EnabledFor(w)&&w.units.Length==16,"new offline scene initializes 16 configured units");Check(hud.Inspect,"selection management available without mode 3");w.setup.modes.SetMode(MouseCommandMode.Interaction);Check(w.setup.modes.CurrentMode==MouseCommandMode.RoadMarch,"mode 3 resolves to click movement");
    var map=w.setup.freeMarchMap;var access=TerrainAccess.Ground|TerrainAccess.Road|TerrainAccess.Forest|TerrainAccess.Mountain|TerrainAccess.Grass;
    Check(map.CanTraverse(new RoadPoint(-1,-5),new RoadPoint(5,-5),access),"road crossing water is traversable without bridge");Check(!map.CanTraverse(new RoadPoint(-1,-7),new RoadPoint(5,-7),access),"river outside roads blocks ground units");
    var path=LocalRoadAStar.Plan(map,access,new Vector3(-12,-4),new Vector3(-3,-4),.2f,100000);float roadDistance=0,totalDistance=0;if(path!=null)for(int i=1;i<path.Count;i++){float length=(float)RoadPoint.Distance(path[i-1],path[i]);totalDistance+=length;if(map.TerrainAt(RoadPoint.Lerp(path[i-1],path[i],.5))==TerrainKind.Road)roadDistance+=length;}Check(path!=null&&roadDistance>totalDistance*.6f,"weighted A-star prefers road detour over direct ground: "+roadDistance+"/"+totalDistance);for(int i=1;i<path.Count;i++)Check(map.CanTraverse(path[i-1],path[i],access),"A-star leg "+i+" traversable");
    var u=w.units.First(x=>x.ownerId=="A"&&x.combatDefinition.role==UnitRole.Infantry);hud.SelectUnit(u);Check(hud.SelectedUnit==u&&selection.Selected==u.GetComponent<ArmyRoadMover>(),"right panel selection and movement selection agree");
    selection.SelectOwned(u.GetComponent<ArmyRoadMover>());local.SetOrder(LocalMarchStyle.Forced);Check(local.Move(new Vector3(-6,-5),null)==1&&u.Motor.IsMoving,"click command commits an executable route");var order=u.GetComponent<LocalMarchOrder>();Check(!order.StopForContact(),"forced march does not stop for contact");u.UnderFire=true;order.style=LocalMarchStyle.Assault;Check(order.StopForContact(),"assault stops under fire");order.style=LocalMarchStyle.Cautious;Check(order.SpeedFactor<1&&order.StopForContact(),"cautious movement is slower and stops under fire");u.UnderFire=false;u.Motor.Stop();
    var enemy=w.units.First(x=>x.ownerId=="B"&&x.combatDefinition.role==UnitRole.Infantry);var old=enemy.transform.position;enemy.transform.position=u.transform.position+Vector3.right*.2f;w.fogEnabled=false;Check(order.StopForContact(),"visible enemy causes cautious contact stop");order.style=LocalMarchStyle.Forced;Check(!order.StopForContact(),"forced march continues past a visible enemy");enemy.transform.position=old;
    var workers=w.units.Where(x=>x.ownerId=="A"&&x.combatDefinition.role==UnitRole.Engineer).ToArray();var works=w.campaign.lineWorks;var rules=works.Rules;var line=new List<Vector3>{new Vector3(-5,-4),new Vector3(-5,-3)};
    Check(Vector2.Distance(workers[0].transform.position,line[0])>workers[0].combatDefinition.visionRadius,"test construction is beyond engineer vision");var build=works.Build(workers[0],line);Check(build.accepted,"remote freehand construction accepted and A-star approach committed: "+build.reason);Check(works.Approaching(workers[0]),"engineer travels to construction site");Check(works.Assist(workers[1],line[0]).accepted,"second engineer joins a project by right-click target");
    workers[0].transform.position=line[0];workers[1].transform.position=line[0];works.Tick(.1f);float before=works.Remaining(workers[0]);works.Tick(1);Check(Mathf.Abs(before-works.Remaining(workers[0])-2)<.02f,"two on-site engineers double construction progress");
    var command=w.GetComponent<BattleCommandService>().Submit(new BattleCommand{kind=BattleCommandKind.FreeDestination,unitId=workers[0].unitId,playerId="A",destination=new Vector3(-8,-5)});Check(!command.accepted&&!works.Working(workers[0])&&!works.Working(workers[1]),"new task cancels current project and releases helpers");
    Check(!works.CanBuild(workers[0],new[]{new Vector3(-10,-5),new Vector3(-4,-5)},out var reason),"per-command wall length limit enforced");
    var truck=w.units.First(x=>x.ownerId=="A"&&x.GetComponent<TransportTruck>()!=null).GetComponent<TransportTruck>();truck.Unit.Motor.Stop();truck.transform.position=w.campaign.logistics.sites[0].transform.position;float stock=w.campaign.logistics.sites[0].stock;local.TickResources(1);Check(truck.Cargo>0&&w.campaign.logistics.sites[0].stock<stock,"truck loads directly from resource area");var city=w.points.First(x=>x.ownerId=="A");truck.transform.position=city.transform.position;float cityStock=city.resourceStock;local.TickResources(1);Check(city.resourceStock>cityStock,"truck unloads directly at friendly city");
    var fx=w.GetComponent<LocalCombatEffects>();int objects=UnityEngine.Object.FindObjectsOfType<LocalEffectParticle>().Length;float hp=u.Personnel;fx.Play(new CombatEffectCue(CombatEffectStage.DirectAttack,true,true,true,UnitRole.Infantry,u.transform.position,u.transform.position+Vector3.right,0));fx.Play(new CombatEffectCue(CombatEffectStage.DirectAttack,true,true,true,UnitRole.Tank,u.transform.position,u.transform.position+Vector3.right,0));fx.Play(new CombatEffectCue(CombatEffectStage.ArtilleryLaunch,true,true,true,UnitRole.Artillery,u.transform.position,u.transform.position+Vector3.right*3,.5f));fx.Play(new CombatEffectCue(CombatEffectStage.ArtilleryImpact,false,true,false,UnitRole.Artillery,Vector3.zero,u.transform.position+Vector3.right*2,1));Check(UnityEngine.Object.FindObjectsOfType<LocalEffectParticle>().Length>objects+100,"infantry, tank, shell trajectory and barrage effects spawn");Check(hp==u.Personnel,"visual effects do not alter combat damage");
    hud.SelectUnit(u);w.setup.mapCamera.transform.position=new Vector3(1.8f,0,-10);w.setup.mapCamera.orthographicSize=10;phase=1;return;
   }
   if(phase==1){File.WriteAllText("local-ui-layout.txt",string.Join("\n",UnityEngine.Object.FindObjectsOfType<Canvas>().SelectMany(c=>c.GetComponentsInChildren<UnityEngine.UI.Image>(true)).Select(i=>i.name+" parent="+i.transform.parent?.name+" size="+i.rectTransform.rect+" active="+i.gameObject.activeInHierarchy)));Capture(w.setup.mapCamera);File.WriteAllText("local-verification.txt",string.Join("\n",results));SessionState.SetBool("LocalVerify",false);EditorApplication.update-=Poll;EditorApplication.Exit(0);}
  }catch(Exception e){File.WriteAllText("local-verification.txt",e+"\n"+string.Join("\n",results));SessionState.SetBool("LocalVerify",false);EditorApplication.update-=Poll;Debug.LogException(e);EditorApplication.Exit(1);}}
  static void Capture(Camera camera){var rt=new RenderTexture(1600,900,24);camera.targetTexture=rt;foreach(var canvas in UnityEngine.Object.FindObjectsOfType<Canvas>()){canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;canvas.overrideSorting=true;canvas.sortingOrder=1000;}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=rt;var t=new Texture2D(1600,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,900),0,0);t.Apply();File.WriteAllBytes("local-preview.png",t.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=null;UnityEngine.Object.Destroy(t);UnityEngine.Object.Destroy(rt);}
 }
}
